INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (8, 2, "vo_minigame_1012_result_1077", 1, 14, 10, 6.58, "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！", 2, 12300143, 1, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (8, 2, "vo_minigame_1012_result_1077", 1, 14, 10, 6.58, "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！", 3, 12300145, 1, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (7, 2, "vo_minigame_1012_result_1078", 1, 9, 5, 4.24, "ふ～ん、まあまあの出来だわ\n悪くはないんだけど…あんたには\nもっともっと期待してるわ～", 1, 12300146, 1, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1079", 1, 9, 5, 4.74, "うん、頑張ったけど…\n正直もっと正解できるかもね～？\nこんなのあんたには通過点！\nさらに良い点目指してみない？", 1, 12300147, 7, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1080", 1, 9, 5, 0, "まあまあな点数だけど、\n自分的に手ごたえはどう？\nダメだって思ってんなら、\nまだまだ伸びる余地ありね！", 1, 12300148, 1, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1081", 1, 9, 5, 2.21, "うん、中々の出来ね！\nでもあんたはもっといい点\n取れるはずよ！\nもっと頑張りましょうか！", 2, 12300149, 8, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1082", 1, 9, 5, 2.46, "ん～はっきり言って微妙ね！\nま、難しい問題だし、\n勉強すれば\n点数は上がっていくと思うわ！", 2, 12300150, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1083", 1, 9, 5, 2.94, "ん～…\n10点には届かなかったか～\n次は10点越え目指して\n頑張ってみない？", 2, 12300151, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1084", 1, 9, 5, 4.19, "はいお疲れ～\n点数的にはまあまあってとこね！\nま、超難問だし頑張ったわよ", 3, 12300152, 7, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1085", 1, 9, 5, 0, "うん、かなり難しい問題なのに\n最後までやり遂げたわね\n次はもっといい点目指してみる？", 3, 12300153, 1, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1086", 1, 9, 5, 2.63, "ちょっとミスが多かったかもね～\nでも間違えた所は復習して\n次は正解するわよー！", 3, 12300154, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1087", 1, 4, 1, 5.53, "あら…あんまり良くない点数ね～\nどうしたの、調子でも悪かった？\n次はもっと頑張りましょうか", 1, 12300155, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_1088", 1, 4, 1, 0.01, "ん～…正解数は\n物足りないわね～\nもうちょっと勉強の時間\n増やしちゃおっか？", 1, 12300156, 3, 3001, 9);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1089", 1, 4, 1, 4.15, "ん～…あんたならもうちょと\nいい点取れんでしょ～？\nもっと頑張んなさいよ\n期待してやってんだからさ！", 1, 12300157, 3, 3001, 3);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, "vo_minigame_1012_result_1090", 1, 4, 1, 0.01, "ん～今のあんたには、\nこの問題は難しかったかしら…\n難易度下げてチャレンジするのも\nありかもね～？", 2, 12300158, 9, 3001, 9);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1091", 1, 4, 1, 5.37, "あんまり出来は良くないわね～\n難しい問題だししょうがないけど\n次はもっと頑張ってほしいわ！", 2, 12300159, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1092", 1, 4, 1, 1.44, "なるほど…\nちょっと苦手な問題が多かった？\nもう一度チャレンジ\nしてみましょうか～", 2, 12300160, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_1093", 1, 4, 1, 0, "んん～…問題が難しすぎた？\n無理に難しい問題続けるより、\n難易度下げた方が\n勉強の効率良いかもよ～？", 3, 12300161, 3, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, "vo_minigame_1012_result_1094", 1, 4, 1, 2.91, "…あんまり点数取れなかったわね\nこれはあたしにも難しい問題だし\nそう落ち込まなくても大丈夫！\n次頑張りましょ！", 3, 12300162, 3, 3001, 3);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, "vo_minigame_1012_result_1095", 1, 4, 1, 2.61, "ごめん、ちょっと難しすぎた？\nもう一度チャレンジするも良し、\n難易度を下げるも良し、\nあんたがやる気なら付き合うわ！", 3, 12300163, 5, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (2, 2, "vo_minigame_1012_result_1096", 1, 0, 0, 3.63, "ちょっとあんた…\nやる気ないわよね～！？\n次こんな点数取ったら\n怒るわよ！", 1, 12300164, 4, 3001, 1);
