INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 2, "vo_minigame_1012_result_2075", 2, 14, 10, 4.21, "おにムズでこのペースは\nすごいんじゃ…？\nうちもがんばってついてくね！", 3, 22300139, 6, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_2078", 2, 9, 5, 1.94, "悪くないよね？\nでもでも\nヒデサイとうちなら\nもっとできる気する！", 1, 22300146, 0, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, "vo_minigame_1012_result_2079", 2, 9, 5, 2.28, "もっと〇ほしーね…\n地道にやるしか\nないっぽいし\nもっかい教えてくれる？", 1, 22300147, 4, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 2, "vo_minigame_1012_result_2080", 2, 9, 5, 0, "ベンキョーしたけど\nわかんないとこばっか…\nヒデサイセンセー、助けて～", 1, 22300148, 4, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_2081", 2, 9, 5, 2.67, "やっぱムズかったね…\nでも次はもうちょい\nできそーな気がするよ！", 2, 22300149, 4, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, "vo_minigame_1012_result_2082", 2, 9, 5, 4.68, "問題ムズいし、この点数は\nありよりのありっしょ？\nえ、もっとできた感じ？", 2, 22300150, 10, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, "vo_minigame_1012_result_2083", 2, 9, 5, 0, "どこ間違ったんだろ？\nうちさっぱりだった…\nやっぱムズいだけあるね", 2, 22300151, 9, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_2084", 2, 9, 5, 3.55, "激ムズだけど\nやることは一緒だよね？\nうちもヒデサイについてくから\nコツコツがんばろ！", 3, 22300152, 0, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, "vo_minigame_1012_result_2085", 2, 9, 5, 2.51, "やっぱおにムズだね…\nそだ、迷ったら\nヒント使うのも\nありよりのあり？", 3, 22300153, 4, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 2, "vo_minigame_1012_result_2086", 2, 9, 5, 6.15, "やっぱテストって\nなんとなくじゃ無理？\n覚えるしかないの？\nじゃあがんばるしかないね…", 3, 22300154, 9, 3001, 0);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, "vo_minigame_1012_result_2087", 2, 4, 1, 4.12, "できたと思ったけど\nそーじゃなかった系？\nテストってマジきびしー…", 1, 22300155, 4, 3001, 6);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 2, "vo_minigame_1012_result_2088", 2, 4, 1, 0.01, "うーん…さっぱり！\nでも簡単な問題なんだよね…？\nもっかいやってみる？", 1, 22300156, 4, 3001, 6);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, "vo_minigame_1012_result_2089", 2, 4, 1, 5.28, "うちらまだまだ\nベンキョーちうだし…\nこれからだよねっ？\nね、ヒデサイ！", 1, 22300157, 0, 3001, 0);
