INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (7, 2, "vo_minigame_1012_result_2091", 2, 4, 1, 5.45, "うちベンキョー苦手でも\nヒデサイとベンキョー\nするのは好き！　だから\nもっかい教えてくれる？", 2, 22300159, 0, 3001, 0);
